impl Default for WasiBudget {
    fn default() -> Self {
        Self {
            calls: 32_768,
            transfer_bytes: 4 * 1024 * 1024,
            work: 32_000_000,
            one_transfer_bytes: 65_536,
            iovecs: 64,
            log_bytes: 65_536,
