        }
    }
}
impl WasiBudget {
    pub fn check(self) -> Result<(), WasiFailure> {
        let max = Self::default();
        if self.calls > max.calls
            || self.transfer_bytes > max.transfer_bytes
            || self.work > max.work
            || self.one_transfer_bytes > max.one_transfer_bytes
            || self.iovecs > max.iovecs
            || self.log_bytes > max.log_bytes
            || self.deadline_ms > max.deadline_ms
        {
            Err(WasiFailure::InvalidBudget)
        } else {
            Ok(())
        }
    }
}

/// Carry the earliest deadline into the actual unchanged WASI context. This
/// method does not construct a context or reset/admit any WASI counters.
pub(crate) fn carry_wasi_deadline(
    &mut self,
    started: Instant,
    budget: WasiBudget,
    cursor: Cursor,
) -> Result<Instant, SwiftRunFailure> {
    self.check(cursor)?;
    if let Err(error) = budget.check() {
        let mut fault = Fault::new(SwiftRunFailureKind::InvalidBudget, "swift_run_wasi_budget");
        fault.wasi_failure = Some(error);
        return Err(self.fail(cursor, fault, None));
    }
    let deadline = started
        .checked_add(Duration::from_millis(budget.deadline_ms))
        .ok_or_else(|| {
            self.fail(
                cursor,
                Fault::new(
                    SwiftRunFailureKind::InvalidBudget,
                    "swift_run_wasi_deadline_overflow",
                ),
                None,
            )
        })?;
    if deadline < self.deadline {
        self.deadline = deadline;
        self.deadline_origin = SwiftDeadlineOrigin::Wasi;
    }
    self.check(cursor)?;
    Ok(self.deadline)
}

pub(crate) fn construct(
    &mut self,
    grants: WasiGrants,
    budget: WasiBudget,
    started: Instant,
    cursor: Cursor,
) -> Result<AccountedWasi, SwiftRunFailure> {
    if self.constructed {
        return Err(self.control.fail(
            cursor,
            Fault::new(
                SwiftRunFailureKind::Invariant,
                "swift_run_wasi_construct_once",
            ),
            None,
        ));
    }
    self.constructed = true;
    let deadline = self.control.carry_wasi_deadline(started, budget, cursor)?;
    let header =
        accounted_header_bytes().ok_or_else(|| layout_failure(self.control, cursor))?;
    let mut partial = Partial::empty();
    let result = (|| {
        partial.header = Some(self.control.admit(
            SwiftReservationCategory::Wasi,
            header,
            cursor,
        )?);
        for (index, bytes) in [
            budget.one_transfer_bytes as usize,
            budget.one_transfer_bytes as usize,
            budget.log_bytes as usize,
            budget.log_bytes as usize,
        ]
        .into_iter()
        .enumerate()
        {
            partial.buffers[index] = Some(self.control.admit(
                SwiftReservationCategory::Wasi,
                bytes,
                cursor,
            )?);
            #[cfg(test)]
            self.checkpoint(index, false);
            self.control.check(cursor)?;
            partial.storage[index]
                .try_reserve_exact(bytes)
                .map_err(|_| {
                    let mut fault = Fault::new(
                        SwiftRunFailureKind::Allocation,
                        "swift_run_wasi_allocation",
                    );
                    fault.wasi_failure = Some(WasiFailure::Allocation);
                    fault.attempted = bytes as u64;
                    self.control.fail(cursor, fault, None)
                })?;
            #[cfg(test)]
            self.checkpoint(index, true);
            self.control
                .exact_capacity(bytes, partial.storage[index].capacity(), cursor)?;
        }
        self.control.check(cursor)
    })();
    if let Err(failure) = result {
        partial.cleanup(self.control);
        return Err(failure);
    }
    let current = partial
        .storage
        .iter()
        .try_fold(size_of::<WasiContext>(), |sum, bytes| {
            sum.checked_add(bytes.capacity())
        });
    let Some(current) = current else {
        let failure = layout_failure(self.control, cursor);
        partial.cleanup(self.control);
        return Err(failure);
    };
